from pathlib import Path
import json

root=Path(__file__).resolve().parents[1]
data=json.loads((root/'content/logic-review.json').read_text())
template=Path(__file__).with_name('logic-review.js').read_text()
(root/'dist/logic-review.js').write_text(
    '/* Generated by scripts/build-logic-review.py. */\nconst bookLogicReview='
    + json.dumps(data,ensure_ascii=False,indent=1)+';\n'+template)
print(f"Built logic review for {len(data['units'])} units.")
